/**
 * Codegen drift (tests-08): regenerating the tools from the vendored spec in memory must
 * reproduce src/tools/generated byte for byte, so a hand edit or an emitter change without
 * `npm run codegen` fails here.
 */
import { readFileSync, readdirSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { generateAll } from "../../src/codegen/generateAll.js";

const root = new URL("../../", import.meta.url);
const spec = JSON.parse(readFileSync(new URL("vendor/snipe-it-rest-api.json", root), "utf8"));
const dir = new URL("src/tools/generated/", root);

describe("codegen drift", () => {
  it("the committed generated files equal a fresh in-memory generation", () => {
    const { files, failures } = generateAll(spec);
    expect(failures).toEqual([]);
    const committed = readdirSync(dir)
      .filter((f) => f.endsWith(".ts"))
      .sort();
    expect(committed).toEqual([...files.keys()].sort());
    const differing = committed.filter((f) => readFileSync(new URL(f, dir), "utf8") !== files.get(f));
    expect(differing).toEqual([]);
  });
});
